describe('Payment Flow - Timeout Redirection', () => {
    beforeEach(() => {
        cy.visit('/payment'); // Navigate to the payment page
    });

    it('should redirect to error page on payment timeout (happy path)', () => {
        // Simulate a payment timeout
        cy.intercept('POST', '/api/payment', {
            statusCode: 408,
            body: { message: 'Payment timeout' },
        }).as('paymentTimeout');

        cy.get('button#submit-payment').click(); // Trigger payment submission
        cy.wait('@paymentTimeout'); // Wait for the payment request to complete

        // Assert that the user is redirected to the error page
        cy.url().should('include', '/error');
        cy.get('h1').should('contain', 'Payment Error');
        cy.get('p').should('contain', 'Your payment has timed out. Please try again.');
    });

    it('should not redirect if payment is successful', () => {
        // Simulate a successful payment
        cy.intercept('POST', '/api/payment', {
            statusCode: 200,
            body: { message: 'Payment successful' },
        }).as('paymentSuccess');

        cy.get('button#submit-payment').click(); // Trigger payment submission
        cy.wait('@paymentSuccess'); // Wait for the payment request to complete

        // Assert that the user is not redirected and remains on the payment page
        cy.url().should('include', '/payment');
        cy.get('.success-message').should('contain', 'Payment processed successfully.');
    });
});
